using UnityEngine; // Required for core engine functionality
public class ShadowController : MonoBehaviour {
    public Light sunLight; // Reference to the scene light
    public void UpdateSunAngle(float angle) {
        // Adjusts the rotation of the light to simulate time-of-day shadow casting
        sunLight.transform.rotation = Quaternion.Euler(angle, 30, 0);
    }
}
